<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{createSchedule,getDoctorsAdmin,getSchedules,updateSchedule,type Schedule}from'../../services/admin';import type{DoctorSummary}from'../../types/medical';import{useAuthStore}from'../../stores/auth';import api from'../../services/api'
const auth=useAuthStore(),isDoctor=computed(()=>auth.user?.role==='doctor')
const rows=ref<Schedule[]>([]),doctors=ref<DoctorSummary[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false),form=reactive({doctor:0,date:'',start_time:'09:00',end_time:'12:00',slot_minutes:30})
const minDate=new Date().toISOString().slice(0,10)
async function load(){loading.value=true;try{rows.value=(await getSchedules()).results}catch{rows.value=[]}finally{loading.value=false}}
async function open(){Object.assign(form,{doctor:0,date:'',start_time:'09:00',end_time:'12:00',slot_minutes:30});dialog.value=true;if(isDoctor.value)form.doctor=(await api.get('doctors/me/')).data.id;else if(!doctors.value.length)doctors.value=await getDoctorsAdmin()}
async function submit(){if(!form.doctor||!form.date){ElMessage.warning('请选择医师和日期');return}if(form.start_time>=form.end_time){ElMessage.warning('结束时间必须晚于开始时间');return}saving.value=true;try{await createSchedule({...form,start_time:`${form.start_time}:00`,end_time:`${form.end_time}:00`});ElMessage.success('排班和号源已生成');dialog.value=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'排班创建失败')}finally{saving.value=false}}
async function toggle(row:Schedule){await updateSchedule(row.id,{is_active:!row.is_active});await load()}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">SCHEDULE & SLOTS</p><h1>排班管理</h1><p>设置医师出诊时段，系统自动切分可预约号源</p></div><el-button type="primary" @click="open">＋ 新建排班</el-button></div><el-card class="table-card"><el-table v-loading="loading" :data="rows"><el-table-column prop="doctor_name" label="医师"/><el-table-column prop="date" label="日期"/><el-table-column prop="time_range" label="出诊时间"/><el-table-column prop="slot_minutes" label="每号分钟"/><el-table-column prop="total_slots" label="总号源"/><el-table-column prop="available_slots" label="剩余"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.is_active?'success':'info'">{{row.is_active?'开放':'关闭'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="toggle(row)">{{row.is_active?'关闭':'开放'}}</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="新建医师排班" width="min(560px,94vw)"><el-form label-position="top"><el-form-item label="出诊医师" required><el-select v-model="form.doctor" filterable style="width:100%"><el-option v-for="item in doctors" :key="item.id" :label="`${item.full_name} · ${item.department_name}`" :value="item.id"/></el-select></el-form-item><el-form-item label="出诊日期" required><el-date-picker v-model="form.date" value-format="YYYY-MM-DD" style="width:100%" :disabled-date="(d:Date)=>d.getTime()<new Date(minDate).setHours(0,0,0,0)"/></el-form-item><el-row :gutter="12"><el-col :span="8"><el-form-item label="开始时间"><el-time-select v-model="form.start_time" start="07:00" step="00:30" end="20:00"/></el-form-item></el-col><el-col :span="8"><el-form-item label="结束时间"><el-time-select v-model="form.end_time" start="07:30" step="00:30" end="21:00"/></el-form-item></el-col><el-col :span="8"><el-form-item label="每号时长"><el-select v-model="form.slot_minutes"><el-option label="15 分钟" :value="15"/><el-option label="20 分钟" :value="20"/><el-option label="30 分钟" :value="30"/></el-select></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">生成排班</el-button></template></el-dialog></section></template>
